import sys
from collections import deque

def main():
    input = sys.stdin.readline
    N, M, S, T = map(int, input().split())
    g = [[] for _ in range(N)]
    edges = []
    for i in range(M):
        u, v = map(int, input().split())
        u -= 1
        v -= 1
        g[u].append((v, i))
        g[v].append((u, i))
        edges.append((u, v))

    S -= 1
    T -= 1

    tin = [-1] * N
    low = [0] * N
    is_bridge = [False] * M
    timer = 0

    stack = [(0, -1, -1, 0)]
    while stack:
        v, p, pe, it = stack.pop()
        if it == 0:
            tin[v] = low[v] = timer
            timer += 1

        if it < len(g[v]):
            to, eid = g[v][it]
            stack.append((v, p, pe, it + 1))
            if eid == pe:
                continue
            if tin[to] == -1:
                stack.append((to, v, eid, 0))
            else:
                low[v] = min(low[v], tin[to])
        else:
            if p != -1:
                low[p] = min(low[p], low[v])
                if low[v] > tin[p]:
                    is_bridge[pe] = True

    comp = [-1] * N
    comp_size = []
    cid = 0
    for i in range(N):
        if comp[i] != -1:
            continue
        q = [i]
        comp[i] = cid
        size = 0
        while q:
            v = q.pop()
            size += 1
            for to, eid in g[v]:
                if is_bridge[eid] or comp[to] != -1:
                    continue
                comp[to] = cid
                q.append(to)
        comp_size.append(size)
        cid += 1

    tree = [[] for _ in range(cid)]
    for u, v in edges:
        cu, cv = comp[u], comp[v]
        if cu != cv:
            tree[cu].append(cv)
            tree[cv].append(cu)

    cs, ct = comp[S], comp[T]
    parent = [-1] * cid
    q = deque([cs])
    parent[cs] = cs
    while q:
        c = q.popleft()
        if c == ct:
            break
        for nc in tree[c]:
            if parent[nc] == -1:
                parent[nc] = c
                q.append(nc)

    path = []
    cur = ct
    while cur != cs:
        path.append(cur)
        cur = parent[cur]
    path.append(cs)

    for c in path:
        if comp_size[c] >= 3:
            print(2 * len(path) - 1)
            return

    print(-1)

if __name__ == "__main__":
    main()
